import os
import json
from pathlib import Path

# Read both policy documents
policy_files = []
for file in os.listdir('.'):
    if file.endswith('.json') and 'policy' in file.lower():
        policy_files.append(file)

print(f"Found policy files: {policy_files}")

policies = {}
for policy_file in policy_files:
    try:
        with open(policy_file, 'r', encoding='utf-8') as f:
            policies[policy_file] = json.load(f)
        print(f"Successfully loaded {policy_file}")
    except Exception as e:
        print(f"Error loading {policy_file}: {e}")

# Analyze the policies to determine the authoritative one
print("\nAnalyzing policies to determine authoritative version...")

# Check for indicators of authority
for filename, policy in policies.items():
    print(f"\n--- {filename} ---")

    # Check for version information
    if 'version' in policy:
        print(f"Version: {policy['version']}")

    # Check for effective date
    if 'effective_date' in policy:
        print(f"Effective Date: {policy['effective_date']}")

    # Check for approval information
    if 'approved_by' in policy:
        print(f"Approved by: {policy['approved_by']}")

    # Check for document status
    if 'status' in policy:
        print(f"Status: {policy['status']}")

    # Check for revision history
    if 'revision_history' in policy:
        print(f"Has revision history: Yes (length: {len(policy['revision_history'])})")

    # Check for comprehensive sections
    if 'sections' in policy:
        print(f"Number of sections: {len(policy['sections'])}")

# Determine authoritative policy based on common indicators
authoritative_policy = None
authoritative_reason = ""

if len(policies) == 1:
    authoritative_policy = list(policies.keys())[0]
    authoritative_reason = "Only one policy document found"
elif len(policies) > 1:
    # Score each policy based on authority indicators
    scores = {}
    for filename, policy in policies.items():
        score = 0

        # Higher version number gets more points
        if 'version' in policy:
            try:
                version_str = str(policy['version'])
                if '.' in version_str:
                    score += float(version_str.split('.')[0]) * 10
                else:
                    score += float(version_str) * 10
            except:
                pass

        # Later effective date gets more points
        if 'effective_date' in policy:
            score += 5

        # Has approval gets points
        if 'approved_by' in policy:
            score += 3

        # "Final" or "Approved" status gets points
        if 'status' in policy and policy['status'].lower() in ['final', 'approved', 'active']:
            score += 4

        # Has revision history gets points
        if 'revision_history' in policy:
            score += 2

        # More comprehensive (more sections) gets points
        if 'sections' in policy:
            score += len(policy['sections']) * 0.5

        scores[filename] = score

    print(f"\nAuthority scores: {scores}")

    # Find the policy with highest score
    authoritative_policy = max(scores, key=scores.get)
    authoritative_reason = f"Highest authority score ({scores[authoritative_policy]}) based on version, date, approval, and completeness"

print(f"\nAuthoritative policy: {authoritative_policy}")
print(f"Reason: {authoritative_reason}")

# Display key information from authoritative policy
if authoritative_policy:
    print(f"\n--- Key Information from Authoritative Policy ({authoritative_policy}) ---")
    auth_policy = policies[authoritative_policy]

    for key in ['title', 'version', 'effective_date', 'status', 'approved_by']:
        if key in auth_policy:
            print(f"{key.replace('_', ' ').title()}: {auth_policy[key]}")

    if 'summary' in auth_policy:
        print(f"\nSummary: {auth_policy['summary'][:200]}...")
